WITH review_input (
  professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
  attendance_required, grade_received, engagement_level, tags, created_at, import_key, course_ids
) AS (
  VALUES 
    (779::BIGINT, 'Es una basura como profesor, no sigue las rúbricas, evalúa como si fuera Dios. No lleven con él.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Clases largas', 'Exámenes retadores']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '8ff1d410a08c17d6fce153b486bc4735b7aa8bd0fbdc13b41258ce25077b9978'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'El profe parece muy buena nota durante la clase, pero califica ridículamente duro, no le importa la rúbrica ni lo que haya mencionado en clase, y si usted le reclama algo, sin importar lo respetuoso que sea su trato hacia él, se va poniendo agresivo. Mejor busque otras opciones.'::TEXT, 2.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor']::TEXT[], '2024-06-21T00:00:00+00:00'::TIMESTAMPTZ, '0cb78027f10e5b1f7ec5e0aec11ccca03cfc18e8673673c534f1a2de2a1e8874'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'Hace el curso de 1 crédito como si fuera de 4, califica muy duro, y en pocas ocasiones se le queda bien con el trabajo realizado, es buena gente y amable, pero el curso se vuelve muy pesado, estresante y cansado con él, si puede vea otras opciones.'::TEXT, 2.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, 'c3cb782f303352004647b176bf5244d55e20ac2e3417c6635a03627517247f5a'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'El profesor, se ve que tiene los conocimientos pero es malo para las clases. En clase se porta muy buena gente y parece que quiere ayudar. Si va a consulta le dice que lo de la clase está malo. Califica duro y no sigue bien la rúbrica. Es pasivo agresivo. Iba a dar puntos extra pero no dio nada.'::TEXT, 4.0::NUMERIC(3,1), 5.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2024-06-20T00:00:00+00:00'::TIMESTAMPTZ, '4f5c68774e88b70bea88d448254ca4a07a38e62db5cfff1e57869580041855f9'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'Este profe literalmente hace que un laboratorio se vuelva difícil. Si usted le pide que le ayude con un infrome / reporte mejor ni tome en cuenta lo que le dice, ya que al final a la hora de evaluarlo no importa lo que le haya dicho simplemente va a calificar como quiera.'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores']::TEXT[], '2024-06-19T00:00:00+00:00'::TIMESTAMPTZ, 'fb96480e493e38ca2e2e0428d1407bce5070376e2bb315521663e46abd1d0fc6'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'El profe es buena gente, pero de verdad hace el curso súper complicado, califica demasiado duro y nunca se le queda bien. Explica bien , pero la verdad es que esa explicación no le va a ayudar para las evaluaciones. Si quiere sufrirla metalo con él, de lo contrario mejor considere otras opciones.'::TEXT, 4.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muchas tareas', 'Exámenes retadores']::TEXT[], '2024-05-31T00:00:00+00:00'::TIMESTAMPTZ, 'ac0e814062f58534a99c22c13bbb977b253a43df670aa834670b8e766764ed50'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'El profe explica bastante bien la materia y brinda mucha ayuda, incluso con las guías de catedra que son bastante confusas. Es muy ordenado con los trabajos y siempre recuerda de las fechas de entrega.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Brinda apoyo', 'Muchos proyectos grupales']::TEXT[], '2023-11-17T00:00:00+00:00'::TIMESTAMPTZ, '441c77f80f4cdc8303a86c327ca6b9699a3ce27925d3d4e329a3512936c5507b'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'El profe enseña la parte de CAD, el curso es simplemente introductorio a ello, las evaluaciones algunas son complicadas, el examen me pareció muy largo para el tiempo que dieron. De igual forma puede certificarse y le dan los puntos de esta sección (no todos lo logran).'::TEXT, 8.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2022-12-03T00:00:00+00:00'::TIMESTAMPTZ, 'ade116c73e00bd85948e8f7552543cec7e46ab4bd2098b225fa9d34bb4e92ebf'::TEXT, ARRAY[4147]::BIGINT[]),
    (779::BIGINT, 'El profe explica muy bien, y lleva el curso de la manera más ordenada posible, como profesro es excelente. Sin embargo sí es bastante exigente con la calificación trabajos por lo que para un curso de 1 crédito puede llegar a tener que trabajar mucho. Da muy buena retroalimentación eso sí'::TEXT, 4.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Da buena retroalimentación', 'Deja trabajos largos']::TEXT[], '2022-11-21T00:00:00+00:00'::TIMESTAMPTZ, 'd987d16ff64aa433db83bd07c3db12a775a2af4e1b8fa2505f5eb74546517159'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Diay, digamos que es bueno. Introduce bien los conceptos, pero a la hora de explicar lo que espera que haga uno se queda corto. Igual es mejor que el otro profe que da el curso. Revise bien las instrucciones de las tareas para no perder un 50% de ella por estupideces.'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Inspirador', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2022-06-03T00:00:00+00:00'::TIMESTAMPTZ, '2e7efae6ea085654486276c5681cdcc2ffd8a79ee034428f381e2e10ef20e201'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Muy buen profe, lo recomiendo, en especial se preocupa por los estudiantes, que estos entiendan y que el curso les resulte útil y no tengo mucho problema para pasar'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Tomaría su clase nuevamente']::TEXT[], '2021-11-29T00:00:00+00:00'::TIMESTAMPTZ, '529b8c5c52324d1b0ef52c759e5b50ade3582886d646a56a57be82d0c9f705cd'::TEXT, ARRAY[4147]::BIGINT[]),
    (779::BIGINT, 'Más cerrado que un bombillo y bien terco. Baja puntos en las calificaciones por cosas que no pidió. Hacerle una consulta por privado es un dolor, sus respuestas no son para nada claras y hasta parece que habla en acertijos. Hace evaluaciones sorpresa.'::TEXT, 4.0::NUMERIC(3,1), 4.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-22T00:00:00+00:00'::TIMESTAMPTZ, 'f7faafaaaa3296f7023ac67e2a1278e5f0a73df0db9c9da001cd97e9bda3ae93'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Excelente profesor, me encantó como dió el curso. En clases se realizan muy pocos ejercicios, por lo que es esencial realizar las guías semanales que él propone. Las evaluaciones son justas y hechas a conciencia ayudan a entender mejor la materia. En consulta es excelente.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('100','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Inspirador', 'Brinda apoyo']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '1acac65de7c7bc7dd193be109e692e0b9550b3da31d06f2adab630030cc1c8a7'::TEXT, ARRAY[1369]::BIGINT[]),
    (779::BIGINT, 'Excelente profesor, siempre atento a consultas, la materia y evaluaciones súper organizadas y la explicación de cada tema excelente, las clases fueron mayoritariamente asincrónicas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Clases excelentes']::TEXT[], '2021-07-18T00:00:00+00:00'::TIMESTAMPTZ, '9a66b8247bda7572d9e8e0f85360c763b2c3ba385f5811a96b6763db8afd4100'::TEXT, ARRAY[1369]::BIGINT[]),
    (779::BIGINT, 'Prepotente como ningun otro.'::TEXT, 6.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2021-07-05T00:00:00+00:00'::TIMESTAMPTZ, 'e5bf1bb064465ef5b3d7865b111be8a2075bf83cf1aeff6d8607c595192ca778'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Me parece que su parte del curso fue buena, aunque la de Esteban Pérez perjudico el curso, explica ejemplos y enseña la programación aunque después haga falta adaptarla a otro caso diferente'::TEXT, 6.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Exámenes retadores', 'Respetado por los estudiantes']::TEXT[], '2021-07-01T00:00:00+00:00'::TIMESTAMPTZ, '19675cad049461e41295cf24f95712030954ee7f3fac86d708bb588b1806ef4c'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'De los mejores profes que hay en la escuela de física en forma presencial, pero virtual fue un poco decepcionante. Si bien hacía el esfuerzo por mandar los videos siempre a tiempo, estos eran muy aburridos y no resolvía un solo ejercicio.Para los exámenes,tareas las fórmulas no explicó.'::TEXT, 4.0::NUMERIC(3,1), 6.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2020-08-24T00:00:00+00:00'::TIMESTAMPTZ, '523a7d96d05a248b1f1a3cf7b52b1ecf4c68df65c89781db3e536ed6e366708d'::TEXT, ARRAY[1369]::BIGINT[]),
    (779::BIGINT, 'Es muy bueno explicando, aunque califica un poco rudo y a veces evalúa ejercicios cuyas fórmulas hay que sacarlas del libro pues no vienen en las presentaciones que proporciona. Es de lo mejor que puede haber en la escuela de física.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Requiere mucha lectura', 'Respetado por los estudiantes', 'Pocos exámenes']::TEXT[], '2020-08-23T00:00:00+00:00'::TIMESTAMPTZ, 'd6586ea151033348397bd58d47b9f4c3d829a13d6aa650dbbeff48584577dac9'::TEXT, ARRAY[1369]::BIGINT[]),
    (779::BIGINT, 'En el top 3 de los profes que me he encontrado en fisica. Explica muy bien, muy respetuoso con el estudiante y las clases son claras.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY['Respetado por los estudiantes', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2020-08-20T00:00:00+00:00'::TIMESTAMPTZ, '916b8a5ccb9171c6d318e8822a26ed8e9d926266ef998eba184957589fced5a2'::TEXT, ARRAY[1369]::BIGINT[]),
    (779::BIGINT, 'Es un buen profesor. Lo único que no lo combierte en uno excelente es que no resuelve ejemplos, pero la explicación teórica es muy clara. Si tiene dudas puede ir a consulta y el lo ayudará a entender mejor.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Respetado por los estudiantes', 'Brinda apoyo']::TEXT[], '2020-08-17T00:00:00+00:00'::TIMESTAMPTZ, 'a19a7e8e35bfc14c0b70af164a55acc0e7036033ebea5d9cbaa9c445da3c3344'::TEXT, ARRAY[1369]::BIGINT[]),
    (779::BIGINT, 'Explica muy bien la parte teórica, las clases son entretenidas, pero nunca explica ejemplos, entonces a la hora de realizar tareas o exámenes hay que leer uno por su cuenta del libro o llega perdido, incluso mete temas y preguntas en los quices de materia que no se vio en clase'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Requiere mucha lectura', 'Aspectos de calificación claros']::TEXT[], '2020-08-13T00:00:00+00:00'::TIMESTAMPTZ, 'be58a48d5f3addf77f0942cbce37b7a7a6c039aa1cd3883c1ae687ffa9d8a8e7'::TEXT, ARRAY[1369]::BIGINT[]),
    (779::BIGINT, 'Es atento, aclara dudas y las clases son claras y entretenidas. El problema es como califica. El curso de un crédito lo va a sufrir. No está claro en qué baja tanto y a veces califica mejor el reporte de práctica que el que de verdad vale puntos. No es el peor, pero meta con otro si puede...'::TEXT, 2.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Muy cómico', 'Muchas tareas']::TEXT[], '2020-02-10T00:00:00+00:00'::TIMESTAMPTZ, '75719a695c154ac67029f5cf2a3c0d76968dad0f954408cc24d1fd2665af51bf'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'pesimo, califica super duro'::TEXT, 2.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-11-06T00:00:00+00:00'::TIMESTAMPTZ, '6f11aec4115c98d201b2463ed141d0a6f994b5fe7c8a1c91e7d0f2adf7df025a'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'No lo metan con el por amor a dios, dice que es un curso de 1 credito y uno pasa 5 dias haciendo un reporte presentable para el, cree que lo que se esta entregando es una tesis, si lo mete preparece para pasar semanas haciendo tesis de licenciatura, no se explica bien lo que quiere que se haga'::TEXT, 2.0::NUMERIC(3,1), 2.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Deja trabajos largos']::TEXT[], '2019-10-16T00:00:00+00:00'::TIMESTAMPTZ, 'd94ef104f816a88bf3ab0f534387dcea620fced2a1f51b4f87dd4bb424cf566f'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'Excelente profesor, explica con claridad y las clases se vuelven amenas. Califica duro.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Brinda apoyo', 'Clases excelentes']::TEXT[], '2019-06-24T00:00:00+00:00'::TIMESTAMPTZ, '82a48ddb62ef9c51f86d806989018606bba746ab984368b764af2a6ed5b17530'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'Es un buen profe. Muy recomendado, califica rudo los informes/reportes/exámenes, pero la clase la vuelve muy amena y es muy ordenado con la materia. Atiende las dudas.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Califica con rigor', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2019-06-12T00:00:00+00:00'::TIMESTAMPTZ, 'b704ffe42710064a6173fb16fab0d83b29d0f75342539aa11aca54470bf80f86'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'Ama lo que hace, procura que la clase sea entretenida y constantemente esta queriendo mejorar sus métodos aplicando tecnologías, transmite energía positiva con solo hablar.'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2019-01-04T00:00:00+00:00'::TIMESTAMPTZ, '78be3ec09274e131fa78b1d2a975f1bee2f89745745d35ce9e59170a13b9ccdb'::TEXT, ARRAY[631]::BIGINT[]),
    (779::BIGINT, 'El profesor es muy bueno explicando, se le entiende muy bien y se nota que le apasiona la física. Hace el curso interactivo, por lo que todas las clases son muy divertidas. Lo único malo que le veo es que los ejercicios que se hace en clase son bastante más sencillos que los del examen.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-23T00:00:00+00:00'::TIMESTAMPTZ, '9284216f9f54412e6f0d9d9b3f46748c5d35c86618ddfd63145700d3bdca13f1'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'se preocupa por que los estudiantes entiendan, últimamente que sea el coordinador de la carrera de ing física, hace que tenga poco tiempo de consulta, y no se puede atener a los ejercicios en clase, no sirven de mucho en el examen'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-06-22T00:00:00+00:00'::TIMESTAMPTZ, '76adb68505776425d438f2e7982f42b68b8429be21a1ffe6ead6c6c268a9ab9c'::TEXT, ARRAY[604]::BIGINT[]),
    (779::BIGINT, 'Demasiado bueno; es buena gente, se preocupa mucho por el estudiante, el porcentaje de las tareas se gana fácil. Da el curso interactivo, los cuestionarios previos son casi inútiles pero fáciles, las preguntas con Plickers ayudan bastante para conceptos pero sí se toma en cuenta si respondió bien.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da crédito extra', 'Tomaría su clase nuevamente']::TEXT[], '2018-06-18T00:00:00+00:00'::TIMESTAMPTZ, '5885fb60d6e344255d4097a86c93a3709287c9d6f0998975ccccf10ba2c3cfd2'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'el mejor profe del curso, buena nota, explica muy claro, siempre se hacen ejercicios en clase parecidos al examen, porcentaje de tareas se gana sencillo. Simplemente un crack'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2018-05-31T00:00:00+00:00'::TIMESTAMPTZ, '3751ce4ecedad3748b84582797e95e264ad2d8cd93182709ffc0e48cd6e6b074'::TEXT, ARRAY[604]::BIGINT[]),
    (779::BIGINT, 'Explica lo necesario, piensa que todos vamos a un ritmo que los más preparados guian y uno a veces se queda perdido, suele ir rápido para no atrasarse, pero no da mucho tiempo para que uno haga los ejercicios, sino que él lo hace de una vez. Por más buenas opiniones, no llevaría con él de nuevo.'::TEXT, 8.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('40','')::SMALLINT, NULL::SMALLINT, ARRAY['Deja trabajos largos']::TEXT[], '2017-12-06T00:00:00+00:00'::TIMESTAMPTZ, 'd4f788f78532208cecb3c4ab03ffe2c2ba3a59a30509151c90ff92122f6bcb50'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Cuando explica la materia no lo hace con mucha claridad, siento que el cree que todos venimos con buenas bases, por lo que se basa solo en las opiniones de las personas que sí saben bastante!'::TEXT, 4.0::NUMERIC(3,1), 3.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('65','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-11-25T00:00:00+00:00'::TIMESTAMPTZ, 'fcde84c1e0b7605e873f956d2818e147791a6019a29a88a987641889e5fdf0db'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'No es un curso sencillo, pero, él ayuda bastates y sus clases son amenas, cordiales y divertidas'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-07-26T00:00:00+00:00'::TIMESTAMPTZ, '652aa011152e0d7a3591979c90bec164097dc0bcd091180849732399f2294fab'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Ninguno'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('75','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-27T00:00:00+00:00'::TIMESTAMPTZ, '0fadee907f894bdae180ba728525f460d54e8299e3ca2c22a0fcf8c5dde524b8'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'El profe no es malo ni bueno, si explica pero tampoco es la gran vara. Divide las tareas de cátedra pero todas valen igual, no elimina notas. Yo al menos no lo llevaría de nuevo con él. xD'::TEXT, 6.0::NUMERIC(3,1), 7.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Requiere mucha lectura', 'La participación importa']::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '57facbb80339702a161636cc3db0d5344d7cdeafeacceb025ba90ba49a859015'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Es un excelente profe, sube presentaciones power point que sirven mucho y además se hacen ejercicios en clase. Toma en cuenta las notas de las tarea y la participación en las preguntas de P.I. Califica muy justo, da puntos si tiene el procedimiento correcto pero mal los datos.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-26T00:00:00+00:00'::TIMESTAMPTZ, '102feef96ebce052f0f25ba5bd3964ca17d22ce0f4ca96285520ac51e2f70fe1'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Excelente profesor. Clases muy dinámicas y participativas, explica muy bien.'::TEXT, 6.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['La participación importa', 'Inspirador', 'Brinda apoyo']::TEXT[], '2017-06-23T00:00:00+00:00'::TIMESTAMPTZ, '628b36c1e7d34aa5413f6ae5676ab8a0fff2430cbdf6f461396c2dffc93d7969'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Demasiado buen profesor, explica super bien, hace ejercicios en clase y esta dispuesto a ayudar si uno lo busca. Eso si haga con ganas los JITT y el PI, porque enserio cuentan en la nota.'::TEXT, 4.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-06-21T00:00:00+00:00'::TIMESTAMPTZ, 'f3e78c95b5c98c32923ad2d30454ca2d4619c0b0131af51af3ddf67990b32fdd'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Buen profe, explica muy bien'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2017-02-10T00:00:00+00:00'::TIMESTAMPTZ, 'da649592c4aef1ae94c7281b88143a8f5188f110064c8bf95eaab1a147f39572'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Super buena persona y profe. De las tareas de catedra y normales solo deja las notas mas altas. Es necesario leerse el capitulo del libro antes de ir a clases.'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Asistencia obligatoria', 'Tomaría su clase nuevamente']::TEXT[], '2017-01-31T00:00:00+00:00'::TIMESTAMPTZ, 'd8702ecc5cc3099e52706b0e2911d399b08a92d56d64076b556f3a974a40c9f6'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Es DEMASIADO buena gente, dispuesto a ayudar al que se lo pida. Siempre esta pendiente de los estudiantes, hace bastantes ejercicios y repite las veces necesarias. Califica justo.'::TEXT, 6.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-30T00:00:00+00:00'::TIMESTAMPTZ, '24d5c237ada5023217c7589f410ca88766938919d74768ad013c0a5ac1bd6487'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Física no se pasa si no se estudia bastante, pero el profe hace todo lo posible para que el alumno pase y aprenda. Deja bastantes tareas que ayudan a que el estudiante practique en la casa y en las clases las hace entretenidas'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('90','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2017-01-25T00:00:00+00:00'::TIMESTAMPTZ, 'd4b00040bfbd52452adf727d1602e597dcb02a47d0de1faed31d75e1d1c9acd6'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Muy buen profe, explica muy bien y califica suave, lo recomiendo'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF(NULL,'')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Aspectos de calificación claros', 'Brinda apoyo']::TEXT[], '2017-01-22T00:00:00+00:00'::TIMESTAMPTZ, 'af2de3af0f55c7aa85365f16860bab1ff27c1534c6fe90d50c0d4e97b1740cf4'::TEXT, ARRAY[604]::BIGINT[]),
    (779::BIGINT, 'Excelente, califica suave pero deja muchas tareas al final elimina las más bajas'::TEXT, 10.0::NUMERIC(3,1), 9.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('80','')::SMALLINT, NULL::SMALLINT, ARRAY['Muy cómico', 'Muchas tareas', 'Requiere mucha lectura']::TEXT[], '2016-12-07T00:00:00+00:00'::TIMESTAMPTZ, '6f0aa491aeef1c071ed6d4147a66aea87a6ae28afff8c1aaa3a18952b27e87d7'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Un ejemplo de profesor, se nota que le gusta enseñar. Explica bien, si no le entiendes algo siempre estará dispuesto a repetirlo. Deja una tarea del libro por cada capítulo, y tareas de cátedra. Califica suave, si completas la idea del ejercicio, pero te equivocas en el procedimiento, te baja poco.'::TEXT, 10.0::NUMERIC(3,1), 8.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), FALSE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Da buena retroalimentación', 'Muchas tareas', 'La participación importa']::TEXT[], '2016-11-29T00:00:00+00:00'::TIMESTAMPTZ, '170a0d3e55546a527fcf76fbfaafd73f98cd5c5ef97dac7f924da260f1eaa6ab'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Es muy buen profesor, 100% recomendado, no hace quices pero si deja bastantes tareas y suele hacer bastante práctica durante la clase y explica excelente'::TEXT, 10.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('70','')::SMALLINT, NULL::SMALLINT, ARRAY[]::TEXT[], '2016-06-28T00:00:00+00:00'::TIMESTAMPTZ, 'eb4d508a8ad54933e51244c3e2eaa8a53a2a21edb272cdb8fb9353c530f379b1'::TEXT, ARRAY[607]::BIGINT[]),
    (779::BIGINT, 'Explica super bien, super comprensivo y deja muchas tareas.'::TEXT, 8.0::NUMERIC(3,1), 10.0::NUMERIC(3,1), NULL::NUMERIC(3,1), NULL::NUMERIC(3,1), TRUE::BOOLEAN, NULLIF('85','')::SMALLINT, NULL::SMALLINT, ARRAY['Muchas tareas', 'Clases excelentes', 'Tomaría su clase nuevamente']::TEXT[], '2016-06-24T00:00:00+00:00'::TIMESTAMPTZ, 'a1fa5da3bb39b22e0b286b30096cc69e78375127959fd175fff3533ac5de100f'::TEXT, ARRAY[607]::BIGINT[])
), inserted_review AS (
  INSERT INTO public.professor_review (
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, status, reviewed_at, created_at, updated_at, import_key
  )
  SELECT 
    professor_id, comment, ease_score, quality_score, clarity_score, fairness_score,
    attendance_required, grade_received, engagement_level, tags, 'approved'::public.professor_review_status, now(), created_at, created_at, import_key
  FROM review_input ri
  WHERE NOT EXISTS (
    SELECT 1 FROM public.professor_review pr WHERE pr.import_key = ri.import_key
  )
  RETURNING id, import_key
), target_review AS (
  SELECT id, import_key FROM inserted_review
  UNION ALL
  SELECT pr.id, pr.import_key
  FROM public.professor_review pr
  JOIN review_input ri ON ri.import_key = pr.import_key
)
INSERT INTO public.professor_review_course (review_id, course_id)
SELECT tr.id, course_id
FROM target_review tr
JOIN review_input ri ON ri.import_key = tr.import_key
CROSS JOIN LATERAL unnest(ri.course_ids) AS course_id
ON CONFLICT DO NOTHING;

COMMIT;
